    await git(["fetch", "--no-tags", credential.remote_url, ref], { network: true });
    remoteHead = (await git(["rev-parse", "--verify", "FETCH_HEAD^{commit}"])).stdout.trim();
    requireProject((await git(["show", `${remoteHead}:.openai/hosting.json`])).stdout);
  }
