  } else if (head && remoteHead && head !== remoteHead) {
    const ahead = await git(["merge-base", "--is-ancestor", remoteHead, head], { check: false });
    if (ahead.code !== 0) {
      const behind = await git(["merge-base", "--is-ancestor", head, remoteHead], { check: false });
